Verificación de tipos
Python nos permite verificar el tipo de cualquier valor con la función type():

# Verificando tipos
print(type(150))           # &lt;class 'int'&gt;
print(type(3.75))          # &lt;class 'float'&gt;
print(type("Perú"))        # &lt;class 'str'&gt;
print(type(True))          # &lt;class 'bool'&gt;

Sintaxis if-elif-else

# Estructura básica
x = 10

if x &lt; 0:
    print("Negativo")
elif x == 0:
    print("Cero")
elif x &lt; 10:
    print("Positivo menor que 10")
else:
    print("10 o mayor")

Estructura básica

# Condicional anidado simple
x = 10

if x &gt; 0:
    print("x es positivo")
    if x &gt; 5:
        print("x es mayor que 5")
    else:
        print("x es menor o igual a 5")
else:
    print("x es cero o negativo")

Alternativa a anidamiento excesivo
Los condicionales muy anidados pueden dificultar la lectura. Es mejor usar elif:

# Evitar anidamiento excesivo
ingreso = 5000
credito = "bueno"
empleo = "estable"

# Mal: muy anidado
if ingreso &gt; 3000:
    if credito == "bueno":
        if empleo == "estable":
            print("Crédito aprobado")
        else:
            print("Crédito denegado: empleo inestable")
    else:
        print("Crédito denegado: mal historial")
else:
    print("Crédito denegado: ingreso bajo")

# Mejor: condiciones combinadas
if ingreso &lt;= 3000:
    print("Crédito denegado: ingreso bajo")
elif credito != "bueno":
    print("Crédito denegado: mal historial")
elif empleo != "estable":
    print("Crédito denegado: empleo inestable")
else:
    print("Crédito aprobado")

# Aún mejor: usar operadores lógicos
if ingreso &gt; 3000 and credito == "bueno" and empleo == "estable":
    print("Crédito aprobado")
else:
    print("Crédito denegado")

